<?php
require_once __DIR__.'/PlanillaPreviewModel.php';
class PlanillaBorradorModel
{
    private $db;public function __construct(PDO $db){$this->db=$db;}
    private function concepto(string $nombre,string $naturaleza,string $tipo):int{$q=$this->db->prepare('SELECT id_concepto_pago FROM conceptos_pago WHERE nombre=? AND naturaleza=? AND tipo=? LIMIT 1');$q->execute([$nombre,$naturaleza,$tipo]);if($id=$q->fetchColumn())return(int)$id;$this->db->prepare("INSERT INTO conceptos_pago(nombre,naturaleza,tipo,estado) VALUES(?,?,?,'ACTIVO')")->execute([$nombre,$naturaleza,$tipo]);return(int)$this->db->lastInsertId();}
    public function generar(int $idPeriodo):int{$vista=(new PlanillaPreviewModel($this->db))->generar($idPeriodo);$this->db->beginTransaction();try{$q=$this->db->prepare('SELECT estado FROM periodos_pago WHERE id_periodo_pago=? FOR UPDATE');$q->execute([$idPeriodo]);$estado=$q->fetchColumn();if(!in_array($estado,['ABIERTO','CALCULADO'],true))throw new RuntimeException('Solo se puede generar o recalcular un período abierto o calculado.');$this->db->prepare('DELETE pc FROM planilla_detalle_conceptos pc JOIN planilla_detalles pd ON pd.id_planilla_detalle=pc.id_planilla_detalle WHERE pd.id_periodo_pago=?')->execute([$idPeriodo]);$guardar=$this->db->prepare("INSERT INTO planilla_detalles(id_periodo_pago,id_vinculo,monto_base,bonificaciones,descuentos,monto_pagar,estado) VALUES(?,?,?,?,?,?,'CALCULADO') ON DUPLICATE KEY UPDATE monto_base=VALUES(monto_base),bonificaciones=VALUES(bonificaciones),descuentos=VALUES(descuentos),monto_pagar=VALUES(monto_pagar),estado='CALCULADO',calculado_en=NOW()");$buscar=$this->db->prepare('SELECT id_planilla_detalle FROM planilla_detalles WHERE id_periodo_pago=? AND id_vinculo=?');$agregar=$this->db->prepare('INSERT INTO planilla_detalle_conceptos(id_planilla_detalle,id_concepto_pago,id_regla,cantidad,importe,explicacion) VALUES(?,?,?,?,?,?)');$n=0;foreach($vista['filas'] as $f){$base=$f['mensual']+$f['pagoHora']+$f['pagoSesion'];$guardar->execute([$idPeriodo,$f['v']['id_vinculo'],$base,$f['bonificaciones'],$f['descuentos'],$f['neto']]);$buscar->execute([$idPeriodo,$f['v']['id_vinculo']]);$detalle=(int)$buscar->fetchColumn();if($f['mensual']>0)$agregar->execute([$detalle,$this->concepto('Remuneración mensual','INGRESO','BASE'),null,$f['diasVigentes'],$f['mensual'],json_encode(['dias'=>$f['diasVigentes'],'feriados'=>$f['feriados']])]);if($f['pagoHora']>0)$agregar->execute([$detalle,$this->concepto('Pago por horas','INGRESO','HORA'),null,$f['horas'],$f['pagoHora'],json_encode(['horas'=>$f['horas']])]);if($f['pagoSesion']>0)$agregar->execute([$detalle,$this->concepto('Pago por sesiones','INGRESO','HORA'),null,$f['a']['sesiones'],$f['pagoSesion'],json_encode(['sesiones'=>$f['a']['sesiones'],'esperadas'=>$f['sesionesEsperadas']])]);foreach($f['reglasAplicadas'] as $r){$ingreso=$r['naturaleza']==='BONIFICACION';$tipo=$ingreso?'BONIFICACION':($r['evento']==='TARDANZA'?'TARDANZA':($r['evento']==='FALTA'?'FALTA':'MANUAL'));$agregar->execute([$detalle,$this->concepto($r['nombre'],$ingreso?'INGRESO':'DESCUENTO',$tipo),$r['id_regla'],$r['cantidad'],$ingreso?$r['importe']:-$r['importe'],json_encode(['evento'=>$r['evento'],'automatico'=>true])]);}$n++;}$this->db->prepare("UPDATE periodos_pago SET estado='CALCULADO' WHERE id_periodo_pago=?")->execute([$idPeriodo]);$this->db->commit();return$n;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
    public function revision(int $idPeriodo):array{$q=$this->db->prepare('SELECT * FROM periodos_pago WHERE id_periodo_pago=?');$q->execute([$idPeriodo]);$periodo=$q->fetch();if(!$periodo)throw new InvalidArgumentException('Período no encontrado.');$q=$this->db->prepare("SELECT pd.*,CONCAT(p.apellidos,', ',p.nombres) trabajador,v.tipo,v.modalidad_pago FROM planilla_detalles pd JOIN vinculos_laborales v ON v.id_vinculo=pd.id_vinculo JOIN personas p ON p.id_persona=v.id_persona WHERE pd.id_periodo_pago=? ORDER BY p.apellidos,p.nombres");$q->execute([$idPeriodo]);$detalles=$q->fetchAll();$conceptos=$this->db->prepare("SELECT pc.*,cp.nombre,cp.naturaleza,cp.tipo FROM planilla_detalle_conceptos pc JOIN conceptos_pago cp ON cp.id_concepto_pago=pc.id_concepto_pago WHERE pc.id_planilla_detalle=? ORDER BY cp.naturaleza DESC,pc.id_detalle_concepto");foreach($detalles as &$d){$conceptos->execute([$d['id_planilla_detalle']]);$d['conceptos']=$conceptos->fetchAll();}unset($d);return compact('periodo','detalles');}
}
